	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeScaleObserve53.cls"), "@IsTest private class GladeScaleObserve53 {\n private static GladeScale53__c base(String name){return new GladeScale53__c(Name=name,Installments__c=3,Schedule_Type__c='Divide By');}\n private static GladeScale53__c queryRow(Id id){return [SELECT Name,Amount__c,Installments__c,Installment_Amount__c,Total__c,NumberMirror__c,NumberWhole__c FROM GladeScale53__c WHERE Id=:id];}\n private static void lifecycle(String cohort,Decimal input){GladeScaleCapture53.events.clear();GladeScale53__c v=base(cohort);v.Amount__c=input;v.NumberMirror__c=input;v.NumberWhole__c=input;List<Object> rows=new List<Object>{new Map<String,Object>{'p'=>'arithmetic','input'=>GladeScaleCapture53.val(input),'scaled'=>GladeScaleCapture53.val(input.setScale(2))},GladeScaleCapture53.row('constructor',v)};insert v;rows.addAll(GladeScaleCapture53.events);rows.add(GladeScaleCapture53.row('inputAfter',v));rows.add(GladeScaleCapture53.row('query',queryRow(v.Id)));GladeScaleCapture53.emit(cohort,rows);}\n @IsTest static void observePositive(){lifecycle('positive',Decimal.valueOf('33.335'));}\n @IsTest static void observeNegative(){lifecycle('negative',Decimal.valueOf('-33.335'));}\n @IsTest static void observeZero(){lifecycle('zero',Decimal.valueOf('0.005'));}\n @IsTest static void observeUpdate(){GladeScale53__c v=base('update');v.Amount__c=100;insert v;GladeScaleCapture53.events.clear();v.Amount__c=Decimal.valueOf('2.675');v.NumberMirror__c=Decimal.valueOf('2.665');v.NumberWhole__c=Decimal.valueOf('-2.5');List<Object> rows=new List<Object>{GladeScaleCapture53.row('assigned',v)};update v;rows.addAll(GladeScaleCapture53.events);rows.add(GladeScaleCapture53.row('inputAfter',v));rows.add(GladeScaleCapture53.row('query',queryRow(v.Id)));GladeScaleCapture53.emit('update',rows);}\n @IsTest static void observeNullOmitted(){GladeScaleCapture53.events.clear();GladeScale53__c omitted=base('omitted');GladeScale53__c explicitNull=base('null');explicitNull.Amount__c=null;explicitNull.NumberMirror__c=null;List<Object> rows=new List<Object>{GladeScaleCapture53.row('constructor',omitted),GladeScaleCapture53.row('constructor',explicitNull)};insert new List<GladeScale53__c>{omitted,explicitNull};rows.addAll(GladeScaleCapture53.events);rows.add(GladeScaleCapture53.row('query',queryRow(omitted.Id)));rows.add(GladeScaleCapture53.row('query',queryRow(explicitNull.Id)));GladeScaleCapture53.emit('nullOmitted',rows);}\n @IsTest static void observeFormulaInstallments(){GladeScaleCapture53.events.clear();GladeScale53__c rd=base('formula');rd.Amount__c=100;Decimal arithmetic=Decimal.valueOf('100')/3;List<Object> rows=new List<Object>{new Map<String,Object>{'p'=>'arithmetic','division'=>GladeScaleCapture53.val(arithmetic),'scaled'=>GladeScaleCapture53.val(arithmetic.setScale(2))},GladeScaleCapture53.row('constructor',rd)};insert rd;rows.addAll(GladeScaleCapture53.events);rows.add(GladeScaleCapture53.row('inputAfter',rd));rd=queryRow(rd.Id);rows.add(GladeScaleCapture53.row('query',rd));Decimal installment=rd.Installment_Amount__c;Decimal remainder=rd.Total__c-2*installment;List<Opportunity> opps=new List<Opportunity>{new Opportunity(Name='first',StageName='Prospecting',CloseDate=Date.newInstance(1970,6,30),Amount=installment),new Opportunity(Name='last',StageName='Prospecting',CloseDate=Date.newInstance(1970,8,30),Amount=remainder)};rows.add(new Map<String,Object>{'p'=>'oppConstructor','first'=>GladeScaleCapture53.val(opps[0].Amount),'last'=>GladeScaleCapture53.val(opps[1].Amount)});insert opps;rows.add(new Map<String,Object>{'p'=>'oppInputAfter','first'=>GladeScaleCapture53.val(opps[0].Amount),'last'=>GladeScaleCapture53.val(opps[1].Amount)});Set<Id> ids=new Map<Id,Opportunity>(opps).keySet();for(Opportunity opp:[SELECT Name,Amount FROM Opportunity WHERE Id IN :ids ORDER BY Name])rows.add(new Map<String,Object>{'p'=>'oppQuery','name'=>opp.Name,'amount'=>GladeScaleCapture53.val(opp.Amount)});GladeScaleCapture53.emit('formulaInstallments',rows);}\n @IsTest static void observeArithmeticBoundaries(){List<Object> rows=new List<Object>();for(String text:new List<String>{'33.334','33.335','33.336','-33.334','-33.335','-33.336','2.675','2.665','0','100'}){Decimal v=Decimal.valueOf(text);rows.add(new Map<String,Object>{'input'=>text,'value'=>GladeScaleCapture53.val(v),'scale'=>v.scale(),'rounded'=>GladeScaleCapture53.val(v.setScale(2)),'division'=>GladeScaleCapture53.val(v/3)});}GladeScaleCapture53.emit('arithmeticBoundaries',rows);}\n @IsTest static void observeDescribe(){List<Object> rows=new List<Object>();for(Schema.SObjectField token:new List<Schema.SObjectField>{GladeScale53__c.Amount__c,GladeScale53__c.Installment_Amount__c,GladeScale53__c.Installments__c,GladeScale53__c.Total__c,GladeScale53__c.NumberMirror__c,GladeScale53__c.NumberWhole__c,Opportunity.Amount}){Schema.DescribeFieldResult d=token.getDescribe();rows.add(new Map<String,Object>{'field'=>d.getName(),'type'=>String.valueOf(d.getType()),'scale'=>d.getScale(),'precision'=>d.getPrecision(),'calculated'=>d.isCalculated(),'formula'=>d.getCalculatedFormula()});}GladeScaleCapture53.emit('describe',rows);}\n}\n")
